DROP TABLE IF EXISTS rbi_payments;
CREATE TABLE rbi_payments (
  month VARCHAR(10),
  upi_volume_lakh DECIMAL(15,2),
  upi_value_crores DECIMAL(15,2),
  neft_volume_lakh DECIMAL(15,2),
  neft_value_crores DECIMAL(15,2),
  imps_volume_lakh DECIMAL(15,2),
  imps_value_crores DECIMAL(15,2),
  credit_card_volume_lakh DECIMAL(15,2),
  credit_card_value_crores DECIMAL(15,2),
  debit_card_volume_lakh DECIMAL(15,2),
  debit_card_value_crores DECIMAL(15,2),
  atm_withdrawal_volume_lakh DECIMAL(15,2),
  atm_withdrawal_value_crores DECIMAL(15,2),
  total_digital_volume_lakh DECIMAL(15,2),
  total_digital_value_crores DECIMAL(15,2)
);

